// Dental Terminology Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: precise definitions and distinctions between similar terms.
import {q, mix} from './q.js';
const KD='Kindle & Dofka, Dental Terminology', NEL='Nelson, Wheeler’s Dental Anatomy, Physiology and Occlusion';
const CARE='Comprehensive Dental Care and Dental Specialties', INST='Dental Instruments', PHARM='Pharmacology & Pain Management', EMER='Emergency Care', REST='Tooth Restorations', HN='Head and Neck Anatomy', RAD='Radiography', LAB='Dental Laboratory Materials and Procedures';

export default {
 id:'dental-terminology-1',
 event:'Dental Terminology',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Kindle & Dofka’s Dental Terminology and Nelson’s Wheeler’s Dental Anatomy, Physiology and Occlusion',
 plan:[{area:CARE,weight:30},{area:INST,weight:10},{area:PHARM,weight:10},{area:EMER,weight:10},{area:REST,weight:10},{area:HN,weight:10},{area:RAD,weight:10},{area:LAB,weight:10}],
 questions:mix([
  q(CARE,'What is an apicoectomy?','Surgical removal of the root tip',['Removal of the entire pulp','Removal of gum tissue','Reshaping of the alveolar bone'],'B','Apic/o refers to the apex (root tip) and -ectomy means removal. An apicoectomy is done when infection persists after root canal treatment.',KD),
  q(CARE,'How does a pulpotomy differ from a pulpectomy?','A pulpotomy removes only the coronal pulp',['A pulpotomy removes the entire pulp','A pulpotomy removes the root tip','A pulpotomy is an extraction'],'D','A pulpotomy removes pulp from the crown and keeps the root pulp vital, often in primary teeth. A pulpectomy removes all pulp tissue.',KD),
  q(CARE,'What is a gingivectomy?','Surgical removal of gum tissue',['Reshaping of bone','Removal of a tooth','Cleaning under the gums'],'A','Gingiv/o means gums. A gingivectomy removes excess or diseased gingiva, for example to reduce pocket depth.',KD),
  q(CARE,'Which procedure removes calculus below the gumline and smooths the root surfaces?','Scaling and root planing',['Routine prophylaxis','Gingivoplasty and recontouring','Apicoectomy'],'C','Scaling and root planing (“deep cleaning”) treats periodontitis. A prophylaxis is routine cleaning of teeth above the gumline.',KD),
  q(CARE,'In Angle’s classification, a patient whose lower jaw sits back relative to the upper jaw, with a large overjet, has:','Class II malocclusion',['Class I malocclusion','Class III malocclusion','Normal occlusion'],'B','Class II (distocclusion) has the mandible back relative to the maxilla. Class III (mesiocclusion) has the mandible forward.',KD),
  q(CARE,'In orthodontics, what holds the archwire in place in a bracket?','A ligature tie or elastic',['A matrix band','A rubber dam clamp','A pontic'],'D','Ligatures (wire or elastic) secure the archwire in the bracket slot so it can move the teeth.',KD),
  q(CARE,'What is osseointegration?','Bone bonding to an implant',['Gum tissue growing over a crown','Root resorption in primary teeth','Fusion of two teeth together'],'A','Successful implants rely on bone growing tightly against the titanium surface, which can take several months.',KD),
  q(CARE,'In implant dentistry, what is the abutment?','The implant-to-crown connector',['The screw placed in the bone','The bone around the implant','The temporary partial denture'],'C','The implant fixture is placed in bone, the abutment attaches to it, and the crown is attached to the abutment.',KD),
  q(CARE,'A thin shell of porcelain bonded to the front of a tooth to improve its appearance is called a:','Veneer',['Crown','Inlay','Bridge'],'B','Veneers are a cosmetic treatment covering the facial surface. A crown covers the entire tooth.',KD),
  q(CARE,'Which agent is commonly used in at-home tooth whitening products?','Carbamide peroxide',['Sodium fluoride','Chlorhexidine','Calcium hydroxide'],'D','Carbamide peroxide breaks down into hydrogen peroxide, which lightens stains. Fluoride strengthens enamel, and chlorhexidine is an antimicrobial rinse.',KD),
  q(CARE,'A child loses a primary molar early. Which appliance keeps the space open for the permanent tooth?','Space maintainer',['Retainer','Night guard','Obturator'],'A','Space maintainers prevent neighboring teeth from drifting into the gap so the permanent tooth can erupt.',KD),
  q(CARE,'What is a dental sealant?','A resin coating for pits and fissures',['A fluoride rinse used once daily','A permanent filling for a cavity','A type of crown for primary teeth'],'C','Sealants flow into the grooves of chewing surfaces and block bacteria and food, mainly on molars.',KD),
  q(CARE,'Painful inflammation of a tooth socket after the blood clot is lost following an extraction is called:','Alveolar osteitis',['Pericoronitis','Gingivitis','Acute osteomyelitis'],'B','Dry socket usually appears a few days after extraction, often of lower third molars, especially in smokers.',KD),
  q(CARE,'What does the term exodontia mean?','The extraction of teeth',['The study of tooth development','The replacement of missing teeth','The treatment of gum disease'],'D','Ex- means out and odont/o means tooth. Exodontia is the practice of removing teeth, part of oral and maxillofacial surgery.',KD),
  q(CARE,'In the dental office lab, why is a vibrator used when pouring stone into an impression?','To remove air bubbles',['To speed up setting','To cool the stone','To trim the model'],'A','Vibration helps the stone flow into all details of the impression without trapping air. A model trimmer shapes the set model.',KD),
  q(INST,'Which instrument is used to loosen a tooth from the periodontal ligament before extraction?','Elevator',['Rongeur','Curette','Explorer'],'C','Elevators wedge between tooth and bone to sever the periodontal ligament and loosen the tooth. Forceps then remove it.',KD),
  q(INST,'Which surgical instrument is used to cut and trim bone?','Rongeur',['Elevator','Scaler','Cotton pliers'],'B','Rongeurs have sharp, cup-shaped jaws that nip and trim alveolar bone, for example during alveoloplasty.',KD),
  q(INST,'How does a curette differ from a sickle scaler?','A curette has a rounded tip for use below the gumline',['A curette has a pointed tip for use above the gumline only','A curette is used to place restorations','A curette is a type of bur'],'D','Curettes have a rounded toe that adapts to root surfaces below the gumline. Sickle scalers have pointed tips for supragingival calculus.',KD),
  q(INST,'Which bur shape is commonly used to remove decay and open into the tooth?','Round bur',['Diamond wheel','Polishing cup','Mandrel'],'A','Round burs are used to remove caries and gain access to the pulp chamber. A mandrel holds discs and other attachments.',KD),
  q(INST,'During root canal treatment, which instrument cleans and shapes the canal?','Endodontic file',['Periodontal probe','Amalgam condenser','Spoon excavator'],'C','Files of increasing size remove pulp tissue and shape the canal walls before it is filled.',KD),
  q(PHARM,'Why is epinephrine added to many local anesthetics such as lidocaine?','It narrows vessels to prolong numbness',['It numbs much faster than lidocaine','It prevents allergic reactions','It reverses the anesthetic afterward'],'B','Vasoconstrictors slow absorption of the anesthetic into the blood, so it lasts longer and less is needed.',KD),
  q(PHARM,'Nitrous oxide sedation is always delivered mixed with which gas?','Oxygen',['Carbon dioxide','Nitrogen only','Helium'],'D','Nitrous oxide is mixed with at least 30% oxygen to keep the patient well oxygenated, and the patient breathes 100% oxygen afterward.',KD),
  q(PHARM,'Which drug is commonly used as a topical anesthetic before an injection?','Benzocaine',['Lidocaine with epinephrine','Ibuprofen','Amoxicillin'],'A','Topical benzocaine gel numbs the mucosa to reduce injection discomfort.',KD),
  q(PHARM,'For which patients may antibiotic premedication be recommended before certain dental procedures?','Patients with prosthetic valves',['All patients over age 50','All patients with braces','Patients with a common cold'],'C','Premedication helps prevent infective endocarditis in high-risk patients, such as those with prosthetic valves or a history of endocarditis.',KD),
  q(PHARM,'Numbness that persists long after a local anesthetic should have worn off is called:','Paresthesia',['Anaphylaxis','Hematoma','Trismus'],'B','Paresthesia is prolonged altered sensation, sometimes from nerve injury during injection or surgery. Trismus is limited mouth opening.',KD),
  q(EMER,'What is a dental abscess?','A localized pocket of pus',['A cyst filled with clear fluid','A bruise of the gums','A fracture of the root'],'D','Abscesses form at the root tip (periapical) or in the gums (periodontal). Swelling that spreads can become an emergency.',KD),
  q(EMER,'Inflammation of the gum tissue around a partly erupted third molar is called:','Pericoronitis',['Periodontitis','Gingival hyperplasia','Alveolar osteitis'],'A','Food and bacteria trapped under the gum flap over an erupting tooth cause pericoronitis.',KD),
  q(EMER,'A patient is still bleeding an hour after an extraction. What is the first step?','Bite firmly on gauze',['Rinse vigorously with water','Sip cold water through a straw','Apply heat to the cheek'],'C','Firm pressure on gauze for 30 minutes helps form a clot. Rinsing, straws and spitting can dislodge the clot.',KD),
  q(EMER,'A tooth is pushed partly out of its socket after a fall. What is this injury called?','Luxation',['Avulsion','Attrition','Abrasion'],'B','Luxation is displacement of a tooth in its socket. Avulsion is complete loss of the tooth from the socket.',KD),
  q(EMER,'A permanent tooth is completely knocked out. Which term describes this injury?','Avulsion',['Intrusion','Concussion','Erosion'],'D','Avulsion is complete displacement. The tooth should be held by the crown, kept moist (milk or saliva) and replanted quickly.',KD),
  q(REST,'How does an onlay differ from an inlay?','An onlay covers one or more cusps',['An onlay fits only inside the tooth','An onlay is made of amalgam only','An onlay replaces a missing tooth'],'A','Inlays fit within the cusps; onlays extend over one or more cusps. Both are made outside the mouth and cemented.',KD),
  q(REST,'In a fixed bridge, what is the pontic?','The replacement tooth',['The crown on the supporting tooth','The cement holding the bridge','The implant placed in the bone'],'C','The pontic is suspended between abutment crowns on neighboring teeth.',KD),
  q(REST,'Dental amalgam is made by combining an alloy of silver, tin and copper with:','Mercury',['Gold','Resin','Porcelain'],'B','Mixing the alloy powder with mercury (trituration) forms a workable mass that hardens in the tooth.',KD),
  q(REST,'What is a full crown?','A restoration that covers the entire visible tooth',['A filling placed in a pit','A device that replaces several teeth','A temporary rinse'],'D','Crowns restore teeth that are badly broken down or after root canal treatment.',KD),
  q(REST,'Before a crown is placed on a badly broken tooth, material may be added to rebuild the tooth. What is this called?','A core buildup',['A pontic','A veneer','A sealant'],'A','A core buildup replaces lost tooth structure to support the crown, sometimes with a post in the root canal.',KD),
  q(HN,'What is the rounded bulge on the lingual surface of anterior teeth near the gumline called?','Cingulum',['Mamelon','Marginal ridge','Fossa'],'C','The cingulum is a lingual bulge on incisors and canines. Mamelons are bumps on the edges of newly erupted incisors.',NEL),
  q(HN,'What are mamelons?','Bumps on new incisor edges',['Deep grooves on molar roots','Extra cusps on premolars','Pits on the lingual surface'],'B','Mamelons are normal on newly erupted incisors and usually wear away with use. Persistent mamelons can suggest an open bite.',NEL),
  q(HN,'What is the furcation of a tooth?','The area where the roots divide',['The tip of the root','The edge of an incisor','The center of the crown'],'D','Furcations are found on multi-rooted teeth. Bone loss into the furcation is a sign of advanced periodontal disease.',NEL),
  q(HN,'Where does the enamel of the crown meet the cementum of the root?','The cementoenamel junction (CEJ)',['The dentinoenamel junction','The apex','The pulp horn'],'A','The CEJ is the “neck” of the tooth, a landmark used when measuring attachment loss.',NEL),
  q(HN,'Which opening on the mandible, near the premolars, lets nerves and vessels reach the chin and lower lip?','Mental foramen',['Mandibular foramen','Incisive foramen','Foramen magnum'],'C','The mental foramen is on the outer surface below the premolars. The mandibular foramen, on the inner ramus, is the target for an inferior alveolar nerve block.',NEL),
  q(RAD,'A radiograph shows teeth that look too long. Which error causes elongation?','Too little vertical angulation',['Too much vertical angulation','Movement of the receptor','Overexposure'],'B','Insufficient vertical angulation elongates images; excessive vertical angulation foreshortens them.',KD),
  q(RAD,'A clear, unexposed curved area on part of a radiograph is called a:','Cone cut',['Elongation','Double exposure','Overlapping'],'D','A cone cut occurs when the beam does not cover the whole receptor because the position indicator device was misaligned.',KD),
  q(RAD,'In the paralleling technique, how is the receptor positioned?','Parallel to the long axis of the tooth',['At a 45-degree angle to the tooth','Perpendicular to the tooth','Outside the mouth'],'A','The receptor is parallel to the tooth, and the beam is directed perpendicular to both, producing accurate images.',KD),
  q(RAD,'What does a dosimeter badge measure?','The wearer’s radiation exposure',['The patient’s exposure','The X-ray machine’s age and output','The darkroom temperature'],'C','Dosimeters monitor occupational exposure so it stays below safe limits.',KD),
  q(RAD,'Which radiograph shows large areas of the upper or lower arch, useful for impacted teeth or jaw fractures?','Occlusal',['Bitewing','Periapical','Cephalometric'],'B','The patient bites on the receptor, which captures a broad view of the arch.',KD),
  q(LAB,'Which gypsum product is the hardest and strongest, used for dies?','Die stone',['Model plaster','Impression plaster','Orthodontic plaster'],'D','Die stone has the least water and the most compact crystals, making it hard and accurate for crown and bridge work.',KD),
  q(LAB,'Which wax is used to record how the upper and lower teeth fit together?','Bite wax',['Rope utility wax','Boxing wax','Inlay wax'],'A','Bite registration wax records the occlusal relationship. Utility and boxing wax are used to modify trays and pour impressions.',KD),
  q(LAB,'Custom impression trays are commonly made from which material?','Acrylic resin',['Alginate','Gypsum','Amalgam'],'C','Self-cured or light-cured acrylic resin is shaped over a model to make a custom tray that fits the patient.',KD),
  q(LAB,'Polyvinyl siloxane is classified as which type of impression material?','Elastomeric',['Hydrocolloid','Gypsum','Wax'],'B','Elastomers such as polyvinyl siloxane are accurate, stable and elastic, often used for crown and bridge impressions.',KD),
  q(LAB,'How can the setting time of alginate be lengthened?','Using cooler water',['Using warmer water','Using less water','Mixing faster'],'D','Cool water slows the chemical reaction, giving more working time. Warm water speeds setting.',KD)
 ],113)
};
